  const ctaLabel = missing && firstMiss ? L(`${firstMiss.name}: yana ${left(firstMiss)} ta tanlang`, `${firstMiss.name}: выберите ещё ${left(firstMiss)}`, `${firstMiss.name}: choose ${left(firstMiss)} more`) : cta[1];
